{
  // charx_vars 扁平变量实验：AI 每轮只写变化的扁平键，平台 setMany 整体写入。
  // 本脚本按当前世界逐键校验：非法值回退到上一份合法值，状态形态的杂键直接删除。
  // FLAT_DEFAULTS 由独立页面各世界默认状态生成；修改世界 schema 后必须同步重新生成。
  const FLAT_DEFAULTS = {
    w1: { reputation: -60, regret_luWenchuan: 0, regret_heQingyan: 0, ev_foreignAccounts: 'locked', ev_wangRecording: 'locked', ev_dualContract: 'locked', ev_brotherMedicalRecord: 'locked', ev_roleReplacementContract: 'locked', ev_incidentVideo: 'locked', wish_nameCleared: false, wish_brotherRescued: false, wish_linRestored: false, wish_contractReleased: false, flag_companyExposed: false, flag_brotherCaseTurning: false, flag_linTruthExplained: false, flag_linReconciled: false, flag_independentProjectComplete: false, flag_goldcraneRecognized: false, hiddenWishStage: 'locked' },
    w2: { influence: -50, regret_xiaoJingheng: 0, regret_peiZhao: 0, ev_grainLedger: 'locked', ev_tradeLedger: 'locked', ev_enemyLetters: 'locked', ev_betrothalDocument: 'locked', ev_motherLetter: 'locked', ev_peiTestimonyCode: 'locked', wish_motherFreed: false, wish_borderSecured: false, wish_peiCleared: false, wish_crownTrustRestored: false, flag_motherCaptivityConfirmed: false, flag_coupExposed: false, flag_regentDefeated: false, flag_peiTruthExplained: false, flag_crownTruthExplained: false, flag_motherProtected: false, flag_imperialProtectionGranted: false, hiddenWishStage: 'locked' },
    w3: { cultivation: 20, leylineStability: 30, regret_xieLinyuan: 0, regret_wenZhaochen: 0, ev_forbiddenStele: 'locked', ev_demonMarkRecord: 'locked', ev_soulRefiningRecord: 'locked', ev_swordScarRubbing: 'locked', ev_leylineChart: 'locked', ev_demonSoulTestimony: 'locked', wish_zhaoxueSaved: false, wish_sacrificeSystemEnded: false, wish_linyuanCleared: false, wish_masterTrustRestored: false, flag_zhaoxueMarkConfirmed: false, flag_conspiracyExposed: false, flag_cultivationUnsealed: false, flag_demonTideStopped: false, flag_linyuanTruthExplained: false, flag_masterTruthExplained: false, flag_zhaoxueFreed: false, flag_freePathGranted: false, hiddenWishStage: 'locked' },
    w4: { equity: 30, publicity: -40, regret_guYan: 0, regret_zhouYuan: 0, ev_willForensics: 'locked', ev_medicalRecord: 'locked', ev_offshoreAccounts: 'locked', ev_nomineeAgreement: 'locked', ev_zhouTransactions: 'locked', ev_guDrugReport: 'locked', wish_fatherRescued: false, wish_assetTransferStopped: false, wish_guYanTruthUnderstood: false, wish_zhouTruthUnderstood: false, flag_fatherSecured: false, flag_doctorConfessed: false, flag_xuSupport: false, flag_conspiracyExposed: false, flag_shareholderVictory: false, flag_guTruthExplained: false, flag_zhouTruthExplained: false, flag_guIndependentChoice: false, flag_professionalGovernance: false, hiddenWishStage: 'locked' },
    w5: { purification: 25, reputation: -60, regret_peiZheng: 0, regret_qinYue: 0, ev_experimentList: 'locked', ev_lureDevice: 'locked', ev_memoryCore: 'locked', ev_transferRoute: 'locked', ev_extractionRecord: 'locked', ev_forgedOrderLog: 'locked', wish_childrenRescued: false, wish_humanExperimentsEnded: false, wish_peiTruthUnderstood: false, wish_qinTruthUnderstood: false, flag_suppressionBroken: false, flag_corpseKingStabilized: false, flag_childrenLocated: false, flag_labCrimesExposed: false, flag_lureDevicesDisabled: false, flag_siegeStopped: false, flag_peiTruthExplained: false, flag_qinTruthExplained: false, flag_safeHavenSecured: false, flag_healthyBoundarySet: false, hiddenWishStage: 'locked' }
  }
  const METRIC_RANGES = { reputation: [-100, 100], influence: [-100, 100], publicity: [-100, 100], cultivation: [0, 100], leylineStability: [0, 100], equity: [0, 100], purification: [0, 100] }
  const EVIDENCE_ORDER = { locked: 0, obtained: 1, public: 2 }
  const HIDDEN_ORDER = { locked: 0, hinted: 1, revealed: 2, completed: 3 }
  const lastValidKey = 'charx_last_valid_values'
  // 页面与平台自身变量，逐键校验时一律不动
  const PAGE_KEYS = ['activeWorldId', 'currentWorldState', 'worldTransition', 'pendingWorldEntry', 'revisitSession', 'worldSettlementReports', 'globalProgress', 'gameplayGuideSeen', 'trueEndingDecision', lastValidKey]
  let lastInvalidSignature = ''

  const isStateLikeKey = (key) => /^(ev|regret|wish|flag)_/.test(key) || key in METRIC_RANGES || key === 'hiddenWishStage'

  function check(key, value, previous) {
    if (key in METRIC_RANGES) {
      const [min, max] = METRIC_RANGES[key]
      return Number.isInteger(value) && value >= min && value <= max
    }
    if (key.startsWith('regret_')) return Number.isInteger(value) && value >= 0 && value <= 100 && value >= previous
    if (key.startsWith('ev_')) {
      if (!(value in EVIDENCE_ORDER)) return false
      const step = EVIDENCE_ORDER[value] - EVIDENCE_ORDER[previous]
      return step >= 0 && step <= 1
    }
    if (key.startsWith('wish_') || key.startsWith('flag_')) return typeof value === 'boolean' && !(previous === true && value === false)
    if (key === 'hiddenWishStage') {
      if (!(value in HIDDEN_ORDER)) return false
      const step = HIDDEN_ORDER[value] - HIDDEN_ORDER[previous]
      return step >= 0 && step <= 1
    }
    return false
  }

  async function reconcile() {
    const all = await $charx.variable.getAll()
    const worldId = /^w[1-5]$/.test(all.activeWorldId) ? all.activeWorldId : 'w1'
    const defaults = FLAT_DEFAULTS[worldId]
    const previous = all[lastValidKey] && typeof all[lastValidKey] === 'object' ? all[lastValidKey] : null
    const writes = {}
    const accepted = {}
    const invalid = []
    for (const key of Object.keys(defaults)) {
      const value = all[key]
      const fallback = previous && key in previous ? previous[key] : defaults[key]
      if (value === undefined || value === null) {
        writes[key] = fallback
        accepted[key] = fallback
      } else if (check(key, value, previous && key in previous ? previous[key] : defaults[key])) {
        accepted[key] = value
      } else {
        writes[key] = fallback
        accepted[key] = fallback
        invalid.push(key)
      }
    }
    // 删除不属于当前世界的状态键与旧快照时代遗留；页面/平台变量不动
    const deletions = []
    for (const key of Object.keys(all)) {
      if (PAGE_KEYS.includes(key) || key in defaults) continue
      if (isStateLikeKey(key) || key === 'charx_last_valid_world_state') deletions.push(key)
    }
    if (Object.keys(writes).length) await $charx.variable.setMany(writes)
    if (typeof $charx.variable.delete === 'function') for (const key of deletions) await $charx.variable.delete(key)
    await $charx.variable.set(lastValidKey, accepted)
    if (invalid.length) {
      const signature = worldId + ':' + invalid.sort().join(',')
      if (signature !== lastInvalidSignature) {
        lastInvalidSignature = signature
        $charx.ui.toast({ text: '部分变量未通过校验，已恢复为上一份合法值：' + invalid.join('、'), type: 'warning' })
      }
    }
  }
  $charx.hooks.on('onReady', reconcile)
  $charx.hooks.on('onMessageReceived', reconcile)
  $charx.hooks.on('onMessageUpdated', reconcile)
}
